function CellEditing({
  caption = "{{caption}}",
  accent = "{{accent}}",
  editValue = "{{editValue}}",
  editing = {{editing}},
  invalid = {{invalid}},
}) {
  const rows = [
    ["#1042", "A. Whitfield", "Shipped", "£64.00"],
    ["#1040", "M. Iqbal", "Shipped", "£22.00"],
    ["#1039", "S. Novak", "Refunded", "£40.00"],
  ];
  const cellStyle = { padding: "10px 14px", borderBottom: "1px solid #24143020", whiteSpace: "nowrap" };
  return (
    <div style={{ maxWidth: 480, borderRadius: 10, border: "1px solid #24143020", overflow: "hidden", font: "14px system-ui, sans-serif", color: "#241430", background: "#FAF7F2" }}>
      <div style={{ overflowX: "auto" }}>
        <table style={{ borderCollapse: "collapse", width: "100%" }}>
          <caption style={{ textAlign: "left", fontWeight: 600, padding: "10px 14px" }}>{caption}</caption>
          <thead>
            <tr style={{ background: accent, color: "#FAF7F2" }}>
              {["Order", "Customer", "Status", "Total"].map((h) => <th key={h} scope="col" style={{ ...cellStyle, borderBottom: "none" }}>{h}</th>)}
            </tr>
          </thead>
          <tbody>
            <tr>
              <td style={{ ...cellStyle, borderLeft: `3px solid ${accent}` }}>#1041</td>
              <td style={cellStyle}>R. Okafor</td>
              <td style={cellStyle}>Processing</td>
              <td style={cellStyle}>
                {editing ? (
                  <label style={{ display: "inline-flex", flexDirection: "column" }}>
                    <span className="sr-only">Total for order #1041</span>
                    <input type="text" defaultValue={editValue} aria-invalid={invalid} style={{ font: "inherit", padding: "4px 6px", borderRadius: 4, width: 84, border: `1px solid ${invalid ? "#c0392b" : "#24143060"}` }} />
                    {invalid && <span role="alert" style={{ display: "block", color: "#c0392b", fontSize: 12, marginTop: 4 }}>Enter a valid amount</span>}
                  </label>
                ) : (
                  <>£{editValue}</>
                )}
              </td>
            </tr>
            {rows.map((row) => (
              <tr key={row[0]}>{row.map((cell, j) => <td key={j} style={cellStyle}>{cell}</td>)}</tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
